package com.twostor.subscribermanager;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity {
    static final int REQ_NOTIFY=70,REQ_BACKUP=71,REQ_RESTORE=72,REQ_EXPORT=73,REQ_IMPORT=74;
    static final SimpleDateFormat DF=new SimpleDateFormat("yyyy/MM/dd",Locale.US); static final SimpleDateFormat DTF=new SimpleDateFormat("yyyy/MM/dd HH:mm:ss",Locale.US);
    DatabaseHelper db; LinearLayout root,list; EditText search; TextView stats; ArrayList<Subscriber> current=new ArrayList<>();
    int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+0.5f);} TextView tv(String s,float sp){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setPadding(dp(12),dp(8),dp(12),dp(8));return t;}
    Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}
    @Override public void onCreate(Bundle b){super.onCreate(b);db=new DatabaseHelper(this);getWindow().setStatusBarColor(Color.rgb(13,71,161));setup();NotificationHelper.create(this);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},REQ_NOTIFY);scheduleAll(this);}
    void setup(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(10),dp(8),dp(10),dp(8));root.setBackgroundColor(Color.rgb(245,247,250));
        LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView title=tv("إدارة المشتركين",22);title.setTypeface(null,1);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button more=btn("⚙ الإعدادات");more.setOnClickListener(v->settings());bar.addView(more);root.addView(bar);
        stats=tv("",15);stats.setBackgroundColor(Color.WHITE);root.addView(stats,new LinearLayout.LayoutParams(-1,-2));
        LinearLayout actions=new LinearLayout(this);Button add=btn("＋ إضافة مشترك");add.setOnClickListener(v->editDialog(null));Button backup=btn("نسخة احتياطية");backup.setOnClickListener(v->backup());actions.addView(add,new LinearLayout.LayoutParams(0,-2,1));actions.addView(backup,new LinearLayout.LayoutParams(0,-2,1));root.addView(actions);
        search=new EditText(this);search.setHint("بحث بالاسم أو الهاتف أو اسم المستخدم أو النوع");search.setSingleLine();search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){refresh();}public void afterTextChanged(android.text.Editable e){}});root.addView(search);
        ScrollView sv=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);sv.addView(list);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);refresh();}
    void refresh(){if(list==null)return;current.clear();current.addAll(db.all(search==null?"":search.getText().toString()));list.removeAllViews();int active=0,expired=0,soon=0,today=0;for(Subscriber s:current){long d=daysLeft(s.endDate);if(d<0)expired++;else if(d==0)today++;else {active++;if(d<=7)soon++;}list.addView(card(s));}stats.setText("الإجمالي: "+current.size()+"    |    فعال: "+active+"    |    قريب: "+soon+"    |    اليوم: "+today+"    |    منتهي: "+expired);}
    View card(Subscriber s){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(10),dp(6),dp(10),dp(6));c.setBackgroundColor(Color.WHITE);TextView a=tv("👤 "+s.name,18);a.setTypeface(null,1);c.addView(a);long d=daysLeft(s.endDate);TextView b=tv("الاشتراك: "+s.type+"    النهاية: "+s.endDate+"    "+status(s),14);b.setTextColor(statusColor(d));c.addView(b);TextView z=tv("الهاتف: "+s.contact+"    المستخدم: "+s.username,13);c.addView(z);LinearLayout buttons=new LinearLayout(this);Button details=btn("التفاصيل");details.setOnClickListener(v->details(s));Button renew=btn("تجديد");renew.setOnClickListener(v->renewDialog(s));Button edit=btn("تعديل");edit.setOnClickListener(v->editDialog(s));Button del=btn("حذف");del.setOnClickListener(v->confirmDelete(s));buttons.addView(details,new LinearLayout.LayoutParams(0,-2,1));buttons.addView(renew,new LinearLayout.LayoutParams(0,-2,1));buttons.addView(edit,new LinearLayout.LayoutParams(0,-2,1));buttons.addView(del,new LinearLayout.LayoutParams(0,-2,1));c.addView(buttons);Space sp=new Space(this);list.addView(c);list.addView(sp,new LinearLayout.LayoutParams(1,dp(5)));return c;}
    int statusColor(long d){if(d<0)return Color.rgb(120,120,120);if(d==0)return Color.RED;if(d<=2)return Color.rgb(230,120,0);if(d<=7)return Color.rgb(200,140,0);return Color.rgb(0,130,70);}
    String status(String end){long d=daysLeft(end);if(end==null||end.isEmpty())return "بدون تاريخ";if(d<0)return "منتهي";if(d==0)return "ينتهي اليوم";if(d<=2)return "ينتهي خلال يومين";if(d<=7)return "تنبيه: متبقي "+d+" أيام";return "فعال";}
    static String today(){return DF.format(new Date());} static String nowDateTime(){return DTF.format(new Date());}
    static Date parse(String s){try{return DF.parse(s);}catch(Exception e){return null;}}
    static long daysLeft(String end){Date d=parse(end),n=parse(today());if(d==null||n==null)return Long.MAX_VALUE;return Math.round((d.getTime()-n.getTime())/86400000.0);}
    static String addDays(String date,int days){Date d=parse(date);if(d==null)return date;Calendar c=Calendar.getInstance();c.setTime(d);c.add(Calendar.DAY_OF_YEAR,days);return DF.format(c.getTime());}
    static int duration(String type,int custom){if("3 أشهر".equals(type))return 90;if("6 أشهر".equals(type))return 180;if("سنة".equals(type))return 365;if("مخصص".equals(type))return Math.max(1,custom);return 30;}
    EditText field(LinearLayout box,String label,String value){box.addView(tv(label,13));EditText e=new EditText(this);e.setText(value==null?"":value);e.setSingleLine(false);box.addView(e);return e;}
    Spinner spinner(LinearLayout box,String value){Spinner sp=new Spinner(this);String[] a={"شهري","3 أشهر","6 أشهر","سنة","مخصص"};ArrayAdapter<String> ad=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a);sp.setAdapter(ad);for(int i=0;i<a.length;i++)if(a[i].equals(value))sp.setSelection(i);box.addView(sp);return sp;}
    void editDialog(Subscriber old){final boolean isNew=old==null;ScrollView sv=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(8),dp(16),dp(8));sv.addView(box);EditText name=field(box,"الاسم الحقيقي *",isNew?"":old.name);EditText contact=field(box,"وسيلة التواصل",isNew?"":old.contact);box.addView(tv("نوع الاشتراك",13));Spinner type=spinner(box,isNew?"شهري":old.type);EditText user=field(box,"اسم المستخدم",isNew?"":old.username);EditText pass=field(box,"كلمة السر",isNew?"":old.password);EditText start=field(box,"تاريخ الاشتراك / آخر دفع (yyyy/MM/dd)",isNew?today():old.startDate);EditText end=field(box,"تاريخ نهاية الاشتراك (يُحسب تلقائياً)",isNew?addDays(today(),30):old.endDate);end.setEnabled(false);EditText custom=field(box,"عدد الأيام إذا كان مخصصاً",isNew?"30":String.valueOf(old.customDays));EditText notes=field(box,"ملاحظات",isNew?"":old.notes);EditText newPass=field(box,"كلمة السر الجديدة",isNew?"":old.newPassword);EditText newNotes=field(box,"الملاحظات الجديدة",isNew?"":old.newNotes);EditText panel=field(box,"معلومات اللوحة",isNew?"":old.panelInfo);type.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){try{int d=Integer.parseInt(custom.getText().toString().trim());end.setText(addDays(start.getText().toString().trim(),duration((String)type.getSelectedItem(),d)));}catch(Exception ignored){}}});start.setOnFocusChangeListener((v,has)->{if(!has){try{int d=Integer.parseInt(custom.getText().toString().trim());end.setText(addDays(start.getText().toString().trim(),duration((String)type.getSelectedItem(),d)));}catch(Exception ignored){}}});custom.setOnFocusChangeListener((v,has)->{if(!has){try{end.setText(addDays(start.getText().toString().trim(),duration((String)type.getSelectedItem(),Integer.parseInt(custom.getText().toString().trim()))));}catch(Exception ignored){}}});AlertDialog dlg=new AlertDialog.Builder(this).setTitle(isNew?"إضافة مشترك":"تعديل المشترك").setView(sv).setNegativeButton("إلغاء",null).setPositiveButton("حفظ",null).create();dlg.setOnShowListener(x->dlg.getButton(-1).setOnClickListener(v->{if(name.getText().toString().trim().isEmpty()){name.setError("الاسم مطلوب");return;}String st=start.getText().toString().trim();if(parse(st)==null){start.setError("استخدم yyyy/MM/dd");return;}int cd=30;try{cd=Integer.parseInt(custom.getText().toString().trim());}catch(Exception ignored){}Subscriber s=isNew?new Subscriber():old;s.name=name.getText().toString().trim();s.contact=contact.getText().toString().trim();s.type=(String)type.getSelectedItem();s.username=user.getText().toString().trim();s.password=pass.getText().toString();s.startDate=st;s.customDays=cd;s.endDate=addDays(st,duration(s.type,cd));s.notes=notes.getText().toString();s.newPassword=newPass.getText().toString();s.newNotes=newNotes.getText().toString();s.panelInfo=panel.getText().toString();if(isNew){s.renewed=false;long id=db.insert(s);if(id>0)dlg.dismiss();}else db.update(s);refresh();scheduleAll(this);dlg.dismiss();}));dlg.show();}
    void renewDialog(Subscriber s){ScrollView sv=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(8),dp(16),dp(8));sv.addView(box);box.addView(tv("تجديد: "+s.name,18));EditText payment=field(box,"تاريخ الدفع الفعلي (yyyy/MM/dd)",today());box.addView(tv("نوع الاشتراك",13));Spinner type=spinner(box,s.type);EditText custom=field(box,"عدد الأيام للمخصص",String.valueOf(s.customDays));TextView preview=tv("",15);box.addView(preview);EditText np=field(box,"كلمة السر الجديدة (اختياري)",s.newPassword);EditText nn=field(box,"الملاحظات الجديدة (اختياري)",s.newNotes);EditText rn=field(box,"ملاحظة التجديد","");Runnable calc=()->{try{int d=Integer.parseInt(custom.getText().toString().trim());String p=payment.getText().toString().trim();preview.setText("النهاية الجديدة: "+addDays(p,duration((String)type.getSelectedItem(),d)));}catch(Exception e){preview.setText("تأكد من التاريخ وعدد الأيام");}};payment.setOnFocusChangeListener((v,h)->{if(!h)calc.run();});type.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int a,long b){calc.run();}});calc.run();AlertDialog dlg=new AlertDialog.Builder(this).setTitle("تجديد الاشتراك").setView(sv).setNegativeButton("إلغاء",null).setPositiveButton("تجديد وحفظ",null).create();dlg.setOnShowListener(x->dlg.getButton(-1).setOnClickListener(v->{String p=payment.getText().toString().trim();if(parse(p)==null){payment.setError("استخدم yyyy/MM/dd");return;}int d=30;try{d=Integer.parseInt(custom.getText().toString().trim());}catch(Exception ignored){}String nt=(String)type.getSelectedItem();String ne=addDays(p,duration(nt,d));String old=s.endDate;s.startDate=p;s.endDate=ne;s.type=nt;s.customDays=d;s.renewed=true;if(!np.getText().toString().isEmpty())s.password=np.getText().toString();s.newPassword=np.getText().toString();if(!nn.getText().toString().isEmpty())s.notes=nn.getText().toString();s.newNotes=nn.getText().toString();db.update(s);db.addRenewal(s.id,p,ne,nt,old,rn.getText().toString());refresh();scheduleAll(this);dlg.dismiss();}));dlg.show();}
    void details(Subscriber s){StringBuilder x=new StringBuilder();x.append("الاسم: ").append(s.name).append("\nوسيلة التواصل: ").append(s.contact).append("\nالنوع: ").append(s.type).append("\nاسم المستخدم: ").append(s.username).append("\nكلمة السر: ").append(s.password).append("\nتاريخ الاشتراك/الدفع: ").append(s.startDate).append("\nتاريخ النهاية: ").append(s.endDate).append("\nالحالة: ").append(status(s.endDate)).append("\nالأيام المتبقية: ").append(daysLeft(s.endDate)).append("\nهل تم التجديد؟ ").append(s.renewed?"نعم":"لا").append("\nالملاحظات: ").append(s.notes).append("\nكلمة السر الجديدة: ").append(s.newPassword).append("\nالملاحظات الجديدة: ").append(s.newNotes).append("\nمعلومات اللوحة: ").append(s.panelInfo).append("\n\n--- سجل التجديدات ---\n");for(String[] r:db.renewals(s.id))x.append("الدفع: ").append(r[0]).append(" | النهاية: ").append(r[1]).append(" | ").append(r[2]).append("\nالموعد السابق: ").append(r[3]).append(" | ملاحظة: ").append(r[4]).append("\n\n");new AlertDialog.Builder(this).setTitle("تفاصيل المشترك").setMessage(x.toString()).setPositiveButton("إغلاق",null).show();}
    void confirmDelete(Subscriber s){new AlertDialog.Builder(this).setTitle("حذف المشترك").setMessage("هل أنت متأكد من حذف "+s.name+"؟ سيتم حذف سجل التجديدات أيضاً.").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(d,w)->{db.delete(s.id);refresh();}).show();}
    void settings(){String[] a={"نسخة احتياطية JSON","استعادة نسخة JSON","تصدير CSV إلى Excel","استيراد CSV","طلب صلاحية الإشعارات","حول التطبيق"};new AlertDialog.Builder(this).setTitle("الإعدادات").setItems(a,(d,which)->{switch(which){case 0:backup();break;case 1:restore();break;case 2:exportCsv();break;case 3:importCsv();break;case 4:if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},REQ_NOTIFY);break;default:new AlertDialog.Builder(this).setTitle("إدارة المشتركين").setMessage("نسخة 1.0.0\nتخزين محلي بدون حساب أو خادم.\nالنسخ الاحتياطي JSON يحفظ المشتركين وسجل التجديدات.").setPositiveButton("حسناً",null).show();}}).show();}
    void backup(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"subscriber_backup_"+today().replace('/','-')+".json");startActivityForResult(i,REQ_BACKUP);}
    void restore(){new AlertDialog.Builder(this).setTitle("استعادة البيانات").setMessage("اختر طريقة الاستعادة. الإضافة تحافظ على البيانات الحالية. الاستبدال يمسح البيانات الحالية أولاً، لذلك خذ نسخة احتياطية قبل الاستبدال.").setPositiveButton("إضافة إلى الحالية",(d,w)->pickRestore(false)).setNeutralButton("استبدال الكل",(d,w)->pickRestore(true)).setNegativeButton("إلغاء",null).show();}
    void pickRestore(boolean replace){getPreferences(MODE_PRIVATE).edit().putBoolean("restore_replace",replace).apply();Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,REQ_RESTORE);}
    void exportCsv(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"subscribers_"+today().replace('/','-')+".csv");startActivityForResult(i,REQ_EXPORT);}
    void importCsv(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("text/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,REQ_IMPORT);}
    @Override protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(c!=RESULT_OK||data==null)return;try{if(r==REQ_BACKUP){BackupUtils.write(this,data.getData(),BackupUtils.makeJson(db));toast("تم إنشاء النسخة الاحتياطية");}else if(r==REQ_RESTORE){boolean replace=getPreferences(MODE_PRIVATE).getBoolean("restore_replace",false);int n=BackupUtils.restore(this,db,data.getData(),replace);refresh();scheduleAll(this);toast("تمت استعادة "+n+" مشترك");}else if(r==REQ_EXPORT){BackupUtils.write(this,data.getData(),CsvUtils.exportCsv(db));toast("تم تصدير CSV");}else if(r==REQ_IMPORT){int n=CsvUtils.importCsv(this,db,data.getData());refresh();scheduleAll(this);toast("تم استيراد "+n+" مشترك");}}catch(Exception e){new AlertDialog.Builder(this).setTitle("خطأ").setMessage(e.getMessage()==null?"تعذر تنفيذ العملية":e.getMessage()).setPositiveButton("حسناً",null).show();}}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    static void scheduleAll(Context c){DatabaseHelper db=new DatabaseHelper(c);for(Subscriber s:db.all(""))schedule(c,s);db.close();}
    static void schedule(Context c,Subscriber s){AlarmManager am=(AlarmManager)c.getSystemService(ALARM_SERVICE);long[] offsets={7,2,1,0};for(long off:offsets){Date d=parse(s.endDate);if(d==null)continue;Calendar cal=Calendar.getInstance();cal.setTime(d);cal.set(Calendar.HOUR_OF_DAY,9);cal.set(Calendar.MINUTE,0);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);cal.add(Calendar.DAY_OF_YEAR,(int)-off);if(cal.getTimeInMillis()<=System.currentTimeMillis())continue;Intent i=new Intent(c,NotificationReceiver.class);i.putExtra("id",s.id);i.putExtra("name",s.name);i.putExtra("title",off==0?"ينتهي الاشتراك اليوم":"تنبيه اشتراك");PendingIntent pi=PendingIntent.getBroadcast(c,(int)((s.id*10)+off),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),pi);}}
}
